from content_common import *

def build(b, N):
    b.h1(2, "ทฤษฎีและงานวิจัยที่เกี่ยวข้อง")
    b.p("บทนี้ทบทวนทฤษฎีและงานวิจัยที่ใช้อธิบายผลการทดลองในบทที่ 4 โดยเริ่มจากวัสดุ (ถ่านชีวภาพ เศษคอนกรีตเหลือทิ้ง และคอนกรีตบล็อกปูพื้น) ต่อด้วยมาตรฐานที่เกี่ยวข้อง จากนั้นอธิบายหลักกลศาสตร์ของกำลังอัดและความหนาแน่น ทฤษฎีแรงเสียดทานและการทดสอบความลื่นไถล และหลักการประเมินวัฏจักรชีวิต ส่วนท้ายสังเคราะห์งานวิจัยที่เกี่ยวข้องในรูปตารางเชิงระบบเพื่อระบุช่องว่างของงานวิจัย")

    # ------------------------------------------------ 2.1
    b.h2("2.1 ถ่านชีวภาพ หรือ ไบโอชาร์ (Biochar)")
    b.p(ot(142, {"[18]": "{c:lehmann2015}", " [19]": "", "[20]": "{c:czajczynska2017}", "[21]": "{c:czajczynska2017}", "ดังแสดงในภาพที่ 2-1": "ดังแสดงใน{fig:pyro}"}))
    b.fig("biochar_photo", op("biochar_photo"), 12.0, "ตัวอย่างวัสดุไบโอชาร์ (ก) ไบโอชาร์จากไม้ไผ่ (ข) ไบโอชาร์จากถ่านกะลาปาล์ม", source="ที่มา: {c:cherdkun2019}")
    b.p(ot(148, {"[24]": "{c:biederman2013}", "[25]": "{c:woolf2010}", "[26]": "{c:ahmad2014}", "[27]": "{c:sangmanee2025}", "ดังแสดงใน ภาพที่ 2-3": "ดังแสดงใน{fig:sem1}"}))
    b.fig("sem1", op("sem1"), 11.5, "ภาพถ่าย SEM ของไบโอชาร์ (A) กำลังขยาย 30 เท่า ขนาดอนุภาค < 0.5 cm (B) กำลังขยาย 1,000 เท่า ขนาดอนุภาค < 0.5 cm (C) กำลังขยาย 30 เท่า บดเป็นผง (D) กำลังขยาย 1,000 เท่า บดเป็นผง", source="ที่มา: {c:sangmanee2025} (ภาพจากงานวิจัยของผู้อื่น โปรดตรวจสอบสิทธิ์การนำภาพมาใช้ก่อนเผยแพร่)")
    b.p(ot(151, {"[28]": "{c:buddee2024}", "ดังแสดงในภาพที่ 2-4": "ดังแสดงใน{fig:sem2}"}))
    b.fig("sem2", op("sem2"), 11.5, "ลักษณะพื้นผิวของตัวดูดซับชานอ้อยก่อนการดูดซับ (ก) หลังการดูดซับ (ข) และตัวดูดซับไบโอชาร์จากชานอ้อยก่อนการดูดซับ (ค) หลังการดูดซับ (ง)", source="ที่มา: {c:buddee2024} (ภาพจากงานวิจัยของผู้อื่น โปรดตรวจสอบสิทธิ์การนำภาพมาใช้ก่อนเผยแพร่)")
    b.p(ot(154))

    b.h3("2.1.1 กลไกของไบโอชาร์ในวัสดุซีเมนต์")
    b.p("เอกสารทบทวนล่าสุดสรุปว่าไบโอชาร์ส่งผลต่อวัสดุซีเมนต์ผ่านกลไกที่ทำงานสวนทางกัน ขึ้นกับปริมาณและคุณสมบัติของไบโอชาร์ {c:zhang2022,senadheera2023,murali2024} กลไกหลักมี 4 ประการ ดังสรุปใน{fig:mech}")
    b.p("<b>(1) ฟิลเลอร์และจุดนิวคลีเอชัน</b> อนุภาคไบโอชาร์ที่ละเอียดมีพื้นผิวพรุนและมีหมู่ฟังก์ชัน จึงเป็นตำแหน่งให้ผลิตภัณฑ์ไฮเดรชันเกาะตัว {c:zhang2022} Ling และคณะ (2023) {c:ling2023} พบว่าที่ปริมาณร้อยละ 3 โดยน้ำหนักไบโอชาร์ส่งเสริมระดับไฮเดรชันของซีเมนต์ และ Gupta และ Kua (2019) {c:gupta2019} รายงานว่าไบโอชาร์ผงละเอียดร้อยละ 1–2 ปรับปรุงกำลังอัดและกำลังดัดของมอร์ตาร์")
    b.p("<b>(2) การบ่มภายใน (internal curing)</b> ไบโอชาร์ที่ดูดซับน้ำไว้ในรูพรุนปลดปล่อยน้ำให้เพสต์ในช่วงที่ความชื้นลดลง Gupta และ Kua (2018) {c:gupta2018c} ศึกษาผลของการแช่ไบโอชาร์ล่วงหน้าต่อกำลังและการซึมผ่านของมอร์ตาร์ ส่วน Chen และคณะ (2022) {c:chen2022} อธิบายว่าการบ่มภายในจากไบโอชาร์ปริมาณมากส่งเสริมไฮเดรชันและการเกิดพอลิเมอร์ของ C-S-H")
    b.p("<b>(3) การเจือจางและความพรุน</b> เมื่อไบโอชาร์เข้ามาแทนที่ซีเมนต์ ปริมาณผลิตภัณฑ์ไฮเดรชันต่อหน่วยปริมาตรลดลง และอนุภาคพรุนที่มีกำลังต่ำเพิ่มความพรุนรวม Wang และคณะ (2020) {c:wang2020} ระบุว่าที่ปริมาณสูงไบโอชาร์ทำให้กำลังลดลงเพราะโครงสร้างพรุนและเปราะ ขณะที่ Hylton และคณะ (2024) {c:hylton2024} สรุปว่ามีงานจำนวนมากรายงานกำลังลดลงเมื่อทดแทนซีเมนต์เกินร้อยละ 5 และพบว่าคุณสมบัติของไบโอชาร์ 3 ประการที่ควบคุมกำลังมากที่สุด ได้แก่ ความอิ่มตัวเริ่มต้น (initial saturation) อัตราส่วน O/C และปริมาณซิลิกอนที่ละลายได้")
    b.p("<b>(4) การกักเก็บคาร์บอน</b> เสถียรภาพของคาร์บอนในไบโอชาร์เป็นพื้นฐานของแนวคิดคอนกรีตคาร์บอนต่ำ Woolf และคณะ (2010) {c:woolf2010} ประเมินศักยภาพทางเทคนิคสูงสุดของการกักเก็บคาร์บอนจากไบโอชาร์ที่ 1.8 Pg CO<sub>2</sub>-C เทียบเท่าต่อปี (ร้อยละ 12 ของการปล่อยปัจจุบัน) แต่เป็นการประเมินสำหรับการใช้ในดิน การนำไปใช้ในคอนกรีตต้องพิจารณาความคงทนของคาร์บอนในวัสดุแยกต่างหาก Chin และคณะ (2025) {c:chin2025} รายงานว่าไบโอชาร์ไม้ไผ่เพิ่มการกักเก็บ CO<sub>2</sub> ของมอร์ตาร์ร้อยละ 53 เทียบกับสูตรควบคุมเมื่อบ่มด้วยการคาร์บอเนชัน")
    b.fig("mech", fp("s_biochar_mech"), 14.0, "กลไกของไบโอชาร์ในเมทริกซ์ซีเมนต์: (ก) ฟิลเลอร์และจุดนิวคลีเอชัน (ข) การบ่มภายใน (ค) การเจือจางและความพรุน (ง) แนวโน้มเชิงแนวคิดของกำลังเทียบกับปริมาณ (ผู้วิจัยสังเคราะห์จาก {c:zhang2022,gupta2018c,wang2020,hylton2024}; ภาพ (ง) เป็นแผนภาพเชิงแนวคิด ไม่ใช่ข้อมูลวัด)")
    b.p("สำหรับไบโอชาร์จากไม้ไผ่โดยเฉพาะ Sacdalan และคณะ (2023) {c:sacdalan2023} รายงานว่าไบโอชาร์ไม้ไผ่ที่กระตุ้นด้วย NaOH แทนซีเมนต์ร้อยละ 2 5 และ 8 ให้กำลังอัดที่ 7 วันต่ำกว่าสูตรอ้างอิงเล็กน้อย แต่ที่ 28 วันสูงกว่าอย่างมีนัยสำคัญ และ Gimbun และคณะ (2025) {c:gimbun2025} รายงานว่าคาร์บอเนตที่เกิดขึ้นเพิ่มกำลังอัดสูงสุดร้อยละ 24 และลดคาร์บอนฟุตพรินต์ลงสูงสุดร้อยละ 5.7 อย่างไรก็ตามงานเหล่านี้ใช้มอร์ตาร์และปริมาณไบโอชาร์ในระดับต่ำ ซึ่งต่างจากบล็อกปูพื้นแบบอัดแน่นที่มีมวลรวมหยาบและอัตราส่วนน้ำต่อซีเมนต์ต่ำมาก ผลที่ได้จึงไม่สามารถถ่ายโอนมาใช้กับงานนี้โดยตรง")

    # ------------------------------------------------ 2.2
    b.h2("2.2 เศษคอนกรีตเหลือทิ้ง")
    b.p(ot(156, {"[29-33]": "{c:tam2018,silva2014}", "[34-38]": "{c:contreras2022}", "[39-45]": "{c:verian2018,nedeljkovic2021}", "[46]": "{c:peiris2025}", "ดังแสดงในภาพที่ 2-5": "ดังแสดงใน{fig:rcaphoto}"}))
    b.fig("rcaphoto", op("rca_photo"), 11.0, "เศษคอนกรีตเหลือทิ้งจากห้องปฏิบัติการทดสอบวัสดุ")
    b.p("เศษคอนกรีตเหลือทิ้งต่างจากมวลรวมธรรมชาติเพราะอนุภาคมีมอร์ตาร์เดิมเกาะอยู่ที่ผิว Verian และคณะ (2018) {c:verian2018} ทบทวนว่าสมบัติของมวลรวมรีไซเคิลที่ส่งผลต่อคอนกรีตใหม่ ได้แก่ มอร์ตาร์เดิมที่เกาะผิว ความหนาแน่น และการดูดซึมน้ำ Nedeljković และคณะ (2021) {c:nedeljkovic2021} ระบุสำหรับมวลรวมละเอียดรีไซเคิลว่าข้อจำกัดหลักคือการดูดซึมน้ำสูง สภาวะความชื้นของอนุภาค การรวมตัวเป็นก้อน และมอร์ตาร์เดิม")
    b.h3("2.2.1 โครงสร้างระดับจุลภาคและบริเวณรอยต่อ (ITZ)")
    b.p("คอนกรีตที่ใช้มวลรวมรีไซเคิลมีบริเวณรอยต่อระหว่างมวลรวมกับเพสต์ (interfacial transition zone, ITZ) สองชั้น คือ ITZ เดิมระหว่างหินเดิมกับมอร์ตาร์เดิม และ ITZ ใหม่ระหว่างอนุภาครีไซเคิลกับเพสต์ใหม่ ดังแสดงใน{fig:rcastruct} ITZ เป็นบริเวณที่โครงสร้างจุลภาคของเพสต์ถูกรบกวนโดยมวลรวม มีความต่อเนื่องแบบค่อยเป็นค่อยไปมากกว่าเป็นชั้นที่มีขอบเขตชัดเจน {c:scrivener2004} Xiao และคณะ (2013) {c:xiao2013} วัดด้วยนาโนอินเดนเทชันพบว่า ITZ เดิมหนา 40–50 µm และ ITZ ใหม่หนา 55–65 µm โดยโมดูลัสของ ITZ เดิมและ ITZ ใหม่เท่ากับร้อยละ 70–80 และ 80–90 ของเพสต์ข้างเคียงตามลำดับ ผลนี้ใช้อธิบายได้ว่าเหตุใด RCA ปริมาณสูงจึงทำให้กำลังและความหนาแน่นลดลง")
    b.fig("rcastruct", fp("s_rca_structure"), 13.0, "โครงสร้างของอนุภาคมวลรวมรีไซเคิลและบริเวณรอยต่อสองชั้น (ผู้วิจัยวาดใหม่ ตัวเลขความหนาและโมดูลัสจาก {c:xiao2013})")
    b.p("ในงานนี้ RCA ที่ใช้มีขนาด 0.30–2.36 มม. จึงทำหน้าที่แทนทรายเป็นหลัก มอร์ตาร์เดิมคิดเป็นสัดส่วนสูงในอนุภาคละเอียดกว่าอนุภาคหยาบ ซึ่งทำให้ผลของความพรุนและการดูดซึมน้ำเด่นกว่า ข้อนี้ผู้วิจัยตั้งเป็นข้อสังเกตจากกลไก ยังไม่ได้ยืนยันด้วยการวัดปริมาณมอร์ตาร์เดิมของวัสดุที่ใช้ " + PH)
    b.p(ot(159, {"[47, 48]": "{c:verian2018,silva2014}", "อย่างไรก็ตามมีงานวิจัยจำนวนมากพบว่าการทดแทนเศษคอนกรีตเหลือทิ้ง ไม่ควรเกินร้อยละ 15 ที่ยังให้ค่าความแข็งแรงเชิงกลที่อยู่ในระดับใช้งานได้ โดยที่ยังสามารถรักษาค่ากำลังอัดที่อัตราร้อยละ 90 ของคอนกรีตที่ใช้มวลรวมธรรมชาติได้หากมีการออกแบบสัดส่วนผสมและควบคุมคุณภาพเศษคอนกรีตเหลือทิ้งอย่างเหมาะสม[49, 50] ดังแสดงในภาพที่ 2-6": "อย่างไรก็ตามงานวิจัยในบล็อกปูพื้นที่ตรวจสอบแล้วเสนอระดับการทดแทนที่แตกต่างกัน เช่น ร้อยละ 20 สำหรับมวลรวมละเอียดรีไซเคิล {c:wangx2019} และไม่เกินร้อยละ 50 เมื่อคำนึงถึงข้อกำหนดการดูดซึมน้ำและกำลังดึง {c:contreras2022} ซึ่งขึ้นกับคุณภาพของมวลรวมและการปรับสภาพ ดังแสดงใน{fig:rcaqc}", "[51, 52]": "{c:akhtar2018,chen2022}", "[53]": "{c:peiris2025}"}))
    b.fig("rcaqc", fp("s_rca_qc"), 14.0, "ขั้นตอนการเตรียมและควบคุมคุณภาพเศษคอนกรีตเหลือทิ้งก่อนใช้แทนมวลรวม (ผู้วิจัยวาดใหม่จากแนวคิดใน {c:verian2018,peiris2025})")
    b.p("Peiris และคณะ (2025) {c:peiris2025} ทบทวนงานกว่า 150 เรื่องและสรุปว่าวิธีกำจัดมอร์ตาร์เดิม (เช่น ball milling และ autogenous cleaning) และวิธีเสริมความแข็งแรง (เช่น carbonation การเคลือบพอลิเมอร์ นาโนซิลิกา) ปรับปรุงความหนาแน่น กำลัง และความต้านทานคลอไรด์ของ RCA ได้ ส่วน Akhtar และ Sarmah (2018) {c:akhtar2018} ใช้ถ่านที่มีซิลิคอนสูงจากของเสียอินทรีย์เพื่อเพิ่มกำลังอัดของคอนกรีตมวลรวมรีไซเคิล ซึ่งสอดคล้องกับแนวคิดของงานนี้ที่ใช้ไบโอชาร์ร่วมกับ RCA")
    b.p(ot(162, {"[9, 20, 54]": "{c:peiris2025,shao2026}"}))
    b.p(ot(163, {"[55]": "{c:wangx2026}"}))
    b.fig("rcacarbon", op("rca_carbon"), 13.0, "ประโยชน์ด้านคาร์บอนจากการรีไซเคิลเศษคอนกรีต (ก) ประโยชน์ด้านคาร์บอนต่อหน่วยของผลิตภัณฑ์รีไซเคิล (ข) ประโยชน์ด้านคาร์บอนรวมของผลิตภัณฑ์รีไซเคิลทั้งหมด", source="ที่มา: {c:wangx2026} (ภาพจากงานวิจัยของผู้อื่น โปรดตรวจสอบสิทธิ์การนำภาพมาใช้ก่อนเผยแพร่)")
    b.p(ot(166, {"[50, 56]": "{c:contreras2022,un2015}", "[57]": "{c:rodriguez2017}"}))

    # ------------------------------------------------ 2.3
    b.h2("2.3 คอนกรีตบล็อกปูพื้น")
    b.p(ot(168, {"[58]": "{c:namarak2018}"}))
    b.fig("pbapps", op("pb_apps"), 12.5, "ตัวอย่างการใช้งานคอนกรีตบล็อกปูพื้น (Concrete Paving Block: CPB)", source="ที่มา: {c:sept2018}")
    b.p(ot(171))
